import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()
    if not lines:
        return
    n = int(lines[0].strip())
    if n == 0:
        return
    values = lines[1:1+n]
    # In case there are fewer lines than n (shouldn't happen for valid input), pad with empty strings
    while len(values) < n:
        values.append("")
    order = []
    counts = {}
    for v in values:
        if v not in counts:
            counts[v] = 0
            order.append(v)
        counts[v] += 1
    out_lines = ["attribute count"]
    for v in order:
        out_lines.append(f"{v} {counts[v]}")
    print("\n".join(out_lines))

if __name__ == "__main__":
    main()

