def main():
    data = sys.stdin.read().split('\n')
    if not data:
        print("mean=0.000000 variance=0.000000")
        return
    try:
        n = int(data[0].strip())
    except (ValueError, IndexError):
        n = 0
    nums = []
    for i in range(1, n + 1):
        line = data[i] if i < len(data) else ''
        parts = line.split()
        for p in parts:
            try:
                nums.append(float(p))
            except ValueError:
                pass
    total = len(nums)
    if total == 0:
        mean = 0.0
        var = 0.0
    else:
        mean = sum(nums) / total
        var = sum((x - mean) ** 2 for x in nums) / total
    print(f"mean={mean:.6f} variance={var:.6f}")

if __name__ == "__main__":
    main()

