import sys
import numpy as np


def main():
    data = sys.stdin.read().split('\n')
    if not data:
        return
    idx = 0
    while idx < len(data) and data[idx].strip() == '':
        idx += 1
    if idx >= len(data):
        return
    n = int(data[idx].strip())
    idx += 1
    numbers = []
    for i in range(n):
        line = data[idx + i] if idx + i < len(data) else ''
        numbers.extend(float(tok) for tok in line.split())
    arr = np.array(numbers, dtype=float)
    if arr.size == 0:
        mean = 0.0
        var = 0.0
    else:
        mean = float(arr.mean())
        var = float(arr.var())
    print("mean=%.6f variance=%.6f" % (mean, var))


if __name__ == '__main__':
    main()
